"""Deterministic synthetic test signals (docs/SPEC.md section 16.2).

Every test signal in the repository is generated by code in this module; no
audio file is ever committed. All generators

* return ``float64`` arrays shaped ``(frames, channels)``,
* take ``sr`` (sample rate) and ``seconds`` keyword arguments where a length
  makes sense, and ``seed`` where randomness is involved,
* are bit-identical for identical arguments within one environment.

Level conventions (AES17 style): ``dbfs`` of a sine is its *peak* amplitude
(so a 0 dBFS sine has an RMS of -3.01 dBFS); ``dbfs`` of noise is its *RMS*.

Contents
--------
* level helpers: :func:`db_to_amp`, :func:`amp_to_db`, :func:`rms_dbfs`,
  :func:`peak_dbfs`, :func:`normalize_peak`, :func:`normalize_rms`
* basics: :func:`sine`, :func:`sweep`, :func:`impulse`, :func:`white_noise`,
  :func:`pink_noise`, :func:`silence`
* measurement conformance: :func:`ebu_tone_sequence`,
  :func:`intersample_peak_signal`
* song building blocks: :func:`kick`, :func:`snare`, :func:`hihat`,
  :func:`bass_line`, :func:`vocal_line`, :func:`pad_chords`
* the song: :func:`song_stems`, :func:`song_sections`, :data:`SONG_ROLES`
* AI-generated-audio defect injectors (SPEC section 6.4): :func:`add_hf_ceiling`,
  :func:`add_shimmer`, :func:`add_head_click`, :func:`add_noise_floor`,
  :func:`add_lowmid_buildup`, :func:`make_overlimited`, :func:`add_dc`,
  :func:`inject_nan`, :func:`antiphase_low`
* known processing for a reference master: :func:`tilt_eq`, :func:`peak_limit`,
  :func:`reference_master_set`
* :func:`stem_sum`, :func:`write_wav`, :func:`read_wav`
"""

from __future__ import annotations

import math
from collections.abc import Iterable, Mapping, Sequence
from pathlib import Path

import numpy as np
import soundfile as sf
from scipy import signal

DEFAULT_SR = 48000

#: Peak overshoot of :func:`intersample_peak_signal` (true peak minus sample peak).
INTERSAMPLE_OVERSHOOT_DB = 20.0 * math.log10(math.sqrt(2.0))

SONG_BPM = 120.0
SONG_KEY = "A minor"
SONG_SECONDS = 8.0

#: Roles of :func:`song_stems`, in the vocabulary of SPEC section 6.1.1 / 6.1.3.
SONG_ROLES = (
    "vocals",
    "backing_vocals",
    "drums",
    "bass",
    "synth",
    "keyboard",
    "guitar",
    "strings",
    "fx",
    "percussion",
    "brass",
    "woodwinds",
)

_BEAT_S = 60.0 / SONG_BPM
_CYCLE_BEATS = 16  # four bars of 4/4

# (chord name, bass MIDI note, chord MIDI notes); one chord per bar.
# Bass roots: A1 55 Hz, F2 87.3 Hz, C2 65.4 Hz, G2 98 Hz (all within 55-110 Hz).
_PROGRESSION = (
    ("Am", 33, (57, 60, 64)),
    ("F", 41, (53, 57, 60)),
    ("C", 36, (55, 60, 64)),
    ("G", 43, (55, 59, 62)),
)

# Lead melody: (start beat, length in beats, MIDI note) within a 16-beat cycle.
_MELODY = (
    (0.0, 1.0, 64), (1.0, 1.0, 62), (2.0, 1.75, 60),
    (4.0, 1.0, 60), (5.0, 1.0, 62), (6.0, 1.5, 64),
    (8.0, 1.0, 67), (9.0, 1.0, 64), (10.0, 1.75, 64),
    (12.0, 1.0, 62), (13.0, 1.0, 60), (14.0, 1.5, 57),
)

FloatArray = np.ndarray


# ---------------------------------------------------------------------------
# Level helpers
# ---------------------------------------------------------------------------


def db_to_amp(db: float) -> float:
    """Convert a level in dB to a linear amplitude factor."""
    return float(10.0 ** (float(db) / 20.0))


def amp_to_db(amp: float, floor_db: float = -400.0) -> float:
    """Convert a linear amplitude to dB (clamped at ``floor_db`` for zero)."""
    amp = abs(float(amp))
    if amp <= 0.0:
        return floor_db
    return max(floor_db, 20.0 * math.log10(amp))


def rms_dbfs(x: FloatArray) -> float:
    """RMS level in dBFS over all samples of all channels."""
    x = np.asarray(x, dtype=np.float64)
    return amp_to_db(math.sqrt(float(np.mean(np.square(x))))) if x.size else -400.0


def peak_dbfs(x: FloatArray) -> float:
    """Sample-peak level in dBFS over all channels."""
    x = np.asarray(x, dtype=np.float64)
    return amp_to_db(float(np.max(np.abs(x)))) if x.size else -400.0


def normalize_peak(x: FloatArray, dbfs: float = -1.0) -> FloatArray:
    """Return a copy of ``x`` scaled so that its sample peak is ``dbfs``."""
    x = np.asarray(x, dtype=np.float64)
    peak = float(np.max(np.abs(x))) if x.size else 0.0
    if peak == 0.0:
        return x.copy()
    return x * (db_to_amp(dbfs) / peak)


def normalize_rms(x: FloatArray, dbfs: float = -20.0) -> FloatArray:
    """Return a copy of ``x`` scaled so that its RMS (all channels) is ``dbfs``."""
    x = np.asarray(x, dtype=np.float64)
    rms = math.sqrt(float(np.mean(np.square(x)))) if x.size else 0.0
    if rms == 0.0:
        return x.copy()
    return x * (db_to_amp(dbfs) / rms)


def frames_for(sr: int, seconds: float) -> int:
    """Number of frames for a duration (rounded to the nearest frame)."""
    return int(round(float(sr) * float(seconds)))


def midi_to_hz(note: float) -> float:
    """Equal-tempered frequency of a MIDI note number (A4 = 69 = 440 Hz)."""
    return 440.0 * 2.0 ** ((float(note) - 69.0) / 12.0)


def _as_2d(x: FloatArray) -> FloatArray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        return x[:, None]
    if x.ndim != 2:
        raise ValueError(f"expected a 1-D or 2-D array, got shape {x.shape}")
    return x


def _channels(mono: FloatArray, channels: int) -> FloatArray:
    if channels < 1:
        raise ValueError("channels must be >= 1")
    return np.repeat(np.asarray(mono, dtype=np.float64)[:, None], channels, axis=1)


def _pan(mono: FloatArray, position: float) -> FloatArray:
    """Constant-power pan of a mono signal; position -1 (left) .. +1 (right)."""
    theta = (float(np.clip(position, -1.0, 1.0)) + 1.0) * math.pi / 4.0
    mono = np.asarray(mono, dtype=np.float64).reshape(-1)
    return np.stack([mono * math.cos(theta), mono * math.sin(theta)], axis=1)


# ---------------------------------------------------------------------------
# Basic signals
# ---------------------------------------------------------------------------


def sine(
    freq: float = 1000.0,
    dbfs: float = -20.0,
    phase: float = 0.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 1.0,
    channels: int = 1,
) -> FloatArray:
    """Sine of peak level ``dbfs`` (AES17: RMS is ``dbfs - 3.01``).

    ``phase`` is the start phase in radians; every channel is identical.
    """
    n = np.arange(frames_for(sr, seconds), dtype=np.float64)
    mono = db_to_amp(dbfs) * np.sin(2.0 * np.pi * float(freq) * n / sr + float(phase))
    return _channels(mono, channels)


def sweep(
    f0: float = 20.0,
    f1: float = 20000.0,
    dbfs: float = -20.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 2.0,
    channels: int = 1,
) -> FloatArray:
    """Logarithmic (exponential) sine sweep from ``f0`` to ``f1``; peak ``dbfs``."""
    if f0 <= 0 or f1 <= 0:
        raise ValueError("sweep frequencies must be positive")
    n = frames_for(sr, seconds)
    t = np.arange(n, dtype=np.float64) / sr
    duration = float(seconds)
    if f0 == f1:
        ph = 2.0 * np.pi * f0 * t
    else:
        k = math.log(f1 / f0)
        ph = 2.0 * np.pi * f0 * duration / k * (np.exp(t * k / duration) - 1.0)
    return _channels(db_to_amp(dbfs) * np.sin(ph), channels)


def impulse(
    at_s: float = 0.0,
    dbfs: float = 0.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 1.0,
    channels: int = 1,
) -> FloatArray:
    """Single-sample (Kronecker) impulse of height ``dbfs`` at ``at_s`` seconds."""
    n = frames_for(sr, seconds)
    mono = np.zeros(n)
    idx = frames_for(sr, at_s)
    if not 0 <= idx < n:
        raise ValueError("impulse position is outside the signal")
    mono[idx] = db_to_amp(dbfs)
    return _channels(mono, channels)


def silence(*, sr: int = DEFAULT_SR, seconds: float = 1.0, channels: int = 1) -> FloatArray:
    """Digital silence."""
    return np.zeros((frames_for(sr, seconds), channels))


def white_noise(
    dbfs: float = -20.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 1.0,
    seed: int = 0,
    channels: int = 1,
) -> FloatArray:
    """Gaussian white noise; each channel independent with RMS exactly ``dbfs``."""
    rng = np.random.default_rng(seed)
    x = rng.standard_normal((frames_for(sr, seconds), channels))
    rms = np.sqrt(np.mean(np.square(x), axis=0, keepdims=True))
    rms[rms == 0.0] = 1.0
    return x / rms * db_to_amp(dbfs)


def pink_noise(
    dbfs: float = -20.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 1.0,
    seed: int = 0,
    channels: int = 1,
    fmin: float = 10.0,
) -> FloatArray:
    """Pink (1/f power) noise by FFT shaping; RMS exactly ``dbfs`` per channel.

    Components below ``fmin`` (and DC) are removed so the level does not wander.
    """
    n = frames_for(sr, seconds)
    rng = np.random.default_rng(seed)
    white = rng.standard_normal((n, channels))
    spec = np.fft.rfft(white, axis=0)
    f = np.fft.rfftfreq(n, d=1.0 / sr)
    shape = np.zeros_like(f)
    keep = f >= max(float(fmin), 1e-9)
    shape[keep] = 1.0 / np.sqrt(f[keep])
    x = np.fft.irfft(spec * shape[:, None], n=n, axis=0)
    rms = np.sqrt(np.mean(np.square(x), axis=0, keepdims=True))
    rms[rms == 0.0] = 1.0
    return x / rms * db_to_amp(dbfs)


# ---------------------------------------------------------------------------
# Measurement conformance signals
# ---------------------------------------------------------------------------


def ebu_tone_sequence(
    levels_dbfs: Sequence[float],
    durations_s: Sequence[float],
    freq: float = 1000.0,
    *,
    sr: int = DEFAULT_SR,
    channels: int = 2,
) -> FloatArray:
    """Phase-continuous sine whose peak level steps through ``levels_dbfs``.

    Modelled on EBU Tech 3341 / 3342 test signals: for example
    ``ebu_tone_sequence([-23], [20])`` is a stereo 1 kHz tone that reads
    -23.0 LUFS integrated, and ``ebu_tone_sequence([-20, -30, -20], [10, 60, 10])``
    is EBU Tech 3341 case 3 (-23 LUFS). Each segment boundary is rounded to
    the nearest frame. A level of ``-inf`` gives silence for that segment.
    """
    if len(levels_dbfs) != len(durations_s):
        raise ValueError("levels_dbfs and durations_s must have the same length")
    bounds = np.cumsum([0.0] + [float(d) for d in durations_s])
    idx = [frames_for(sr, b) for b in bounds]
    n = idx[-1]
    amp = np.zeros(n)
    for (a, b), level in zip(zip(idx[:-1], idx[1:]), levels_dbfs):
        amp[a:b] = 0.0 if math.isinf(level) and level < 0 else db_to_amp(level)
    t = np.arange(n, dtype=np.float64)
    return _channels(amp * np.sin(2.0 * np.pi * float(freq) * t / sr), channels)


def intersample_peak_signal(
    sample_peak_dbfs: float = 0.0,
    *,
    sr: int = DEFAULT_SR,
    seconds: float = 1.0,
    channels: int = 2,
    freq: float | None = None,
) -> FloatArray:
    """fs/4 sine with 45 degree phase: every sample sits at +-0.707 of the crest.

    The sample peak is ``sample_peak_dbfs`` while the true (reconstructed)
    peak is ``sample_peak_dbfs + INTERSAMPLE_OVERSHOOT_DB`` (+3.01 dB). A
    sample-peak meter therefore under-reads by 3.01 dB (SPEC S-01, P-14).
    """
    f = sr / 4.0 if freq is None else float(freq)
    amplitude = db_to_amp(sample_peak_dbfs + INTERSAMPLE_OVERSHOOT_DB)
    n = np.arange(frames_for(sr, seconds), dtype=np.float64)
    mono = amplitude * np.sin(2.0 * np.pi * f * n / sr + math.pi / 4.0)
    return _channels(mono, channels)


# ---------------------------------------------------------------------------
# Internal synthesis helpers
# ---------------------------------------------------------------------------


def _sos_lowpass(sr: int, hz: float, order: int = 4):
    return signal.butter(order, hz, btype="lowpass", fs=sr, output="sos")


def _sos_highpass(sr: int, hz: float, order: int = 4):
    return signal.butter(order, hz, btype="highpass", fs=sr, output="sos")


def _sos_bandpass(sr: int, lo: float, hi: float, order: int = 4):
    return signal.butter(order, [lo, hi], btype="bandpass", fs=sr, output="sos")


def _peaking_sos(sr: int, f0: float, gain_db: float, q: float) -> FloatArray:
    """RBJ cookbook peaking EQ as a single SOS section."""
    a = 10.0 ** (gain_db / 40.0)
    w0 = 2.0 * math.pi * f0 / sr
    alpha = math.sin(w0) / (2.0 * q)
    b = np.array([1.0 + alpha * a, -2.0 * math.cos(w0), 1.0 - alpha * a])
    den = np.array([1.0 + alpha / a, -2.0 * math.cos(w0), 1.0 - alpha / a])
    return np.concatenate([b / den[0], den / den[0]])[None, :]


def _filt(sos, x: FloatArray) -> FloatArray:
    return signal.sosfilt(sos, x, axis=0)


def _saw(cycles: FloatArray, dt: float) -> FloatArray:
    """Band-limited (polyBLEP) sawtooth from a phase in cycles and a constant f/sr."""
    t = cycles - np.floor(cycles)
    y = 2.0 * t - 1.0
    idx = np.flatnonzero(t < dt)
    u = t[idx] / dt
    y[idx] -= u + u - u * u - 1.0
    idx = np.flatnonzero(t > 1.0 - dt)
    u = (t[idx] - 1.0) / dt
    y[idx] -= u * u + u + u + 1.0
    return y


def _env(n: int, sr: int, hold_s: float, attack_s: float, release_s: float,
         decay_tau_s: float | None = None) -> FloatArray:
    """Attack ramp, optional exponential decay, linear release after ``hold_s``."""
    t = np.arange(n, dtype=np.float64) / sr
    env = np.minimum(1.0, t / max(attack_s, 1.0 / sr))
    if decay_tau_s is not None:
        env = env * np.exp(-np.maximum(t - attack_s, 0.0) / decay_tau_s)
    rel = np.clip(1.0 - (t - hold_s) / max(release_s, 1.0 / sr), 0.0, 1.0)
    return env * np.where(t > hold_s, rel, 1.0)


def _add_at(buf: FloatArray, start: int, seg: FloatArray) -> None:
    if start >= buf.shape[0] or start + seg.shape[0] <= 0:
        return
    s0 = max(start, 0)
    s1 = min(start + seg.shape[0], buf.shape[0])
    buf[s0:s1] += seg[s0 - start:s1 - start]


def _cycle_times(seconds: float, beats: Iterable[float]) -> list[tuple[float, int]]:
    """Absolute times (s) of beat positions repeated every 16-beat cycle.

    Returns ``(time_s, beat_index_within_cycle_position)`` pairs ordered in time.
    """
    beats = list(beats)
    cycle_s = _CYCLE_BEATS * _BEAT_S
    out: list[tuple[float, int]] = []
    c = 0
    while c * cycle_s < seconds:
        for i, b in enumerate(beats):
            t = c * cycle_s + b * _BEAT_S
            if t < seconds:
                out.append((t, i))
        c += 1
    out.sort()
    return out


def _chord_at(t: float):
    bar = int(t // (4 * _BEAT_S))
    return _PROGRESSION[bar % len(_PROGRESSION)]


def song_sections(seconds: float = SONG_SECONDS) -> dict[str, tuple[float, float]]:
    """Section map of :func:`song_stems`: first half quiet, second half loud.

    The boundary has a 50 ms crossfade centred on it; measure sections with a
    small guard band around the boundary.
    """
    b = float(seconds) / 2.0
    return {"quiet": (0.0, b), "loud": (b, float(seconds))}


def _section_weight(n: int, sr: int, seconds: float, xfade_s: float = 0.05) -> FloatArray:
    """0 in the quiet section, 1 in the loud one, raised-cosine crossfade between."""
    b = song_sections(seconds)["loud"][0]
    t = np.arange(n, dtype=np.float64) / sr
    w = np.clip((t - (b - xfade_s / 2.0)) / xfade_s, 0.0, 1.0)
    return 0.5 - 0.5 * np.cos(np.pi * w)


def _section_curve(weight: FloatArray, quiet_db: float | None, loud_db: float | None) -> FloatArray:
    """Per-sample gain: ``quiet_db`` in the quiet section, ``loud_db`` in the loud one.

    ``None`` means the part is absent in that section.
    """
    gq = 0.0 if quiet_db is None else db_to_amp(quiet_db)
    gl = 0.0 if loud_db is None else db_to_amp(loud_db)
    return (gq + (gl - gq) * weight)[:, None]


# ---------------------------------------------------------------------------
# Song building blocks (mono, shaped (frames, 1))
# ---------------------------------------------------------------------------


def kick(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    freq: float = 55.0,
    beats: Sequence[float] = tuple(float(b) for b in range(_CYCLE_BEATS)),
) -> FloatArray:
    """Pitched, decaying sine kick (sweep 160 Hz -> ``freq``) with a short click.

    ``beats`` are positions within the 16-beat cycle at 120 BPM (default: four
    on the floor). The fundamental settles at ``freq`` (55 Hz = A1, the tonic),
    so energy is concentrated below 250 Hz.
    """
    rng = np.random.default_rng([seed, 101])
    n = frames_for(sr, seconds)
    out = np.zeros(n)
    hit_n = frames_for(sr, 0.45)
    t = np.arange(hit_n) / sr
    f_inst = freq + (160.0 - freq) * np.exp(-t / 0.025)
    body = np.sin(2.0 * np.pi * np.cumsum(f_inst) / sr)
    body *= _env(hit_n, sr, 0.40, 0.002, 0.05, decay_tau_s=0.16)
    click_n = frames_for(sr, 0.004)
    hp = _sos_highpass(sr, 2000.0, 2)
    for t0, _ in _cycle_times(seconds, beats):
        click = _filt(hp, rng.standard_normal(click_n)) * np.exp(-np.arange(click_n) / (sr * 0.001))
        hit = body.copy()
        hit[:click_n] += 0.08 * click
        _add_at(out, frames_for(sr, t0), hit)
    return out[:, None]


def snare(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    beats: Sequence[float] = (1.0, 3.0, 5.0, 7.0, 9.0, 11.0, 13.0, 15.0),
) -> FloatArray:
    """Snare: 190 Hz decaying tone plus band-passed noise burst (1-8 kHz)."""
    rng = np.random.default_rng([seed, 102])
    n = frames_for(sr, seconds)
    out = np.zeros(n)
    hit_n = frames_for(sr, 0.3)
    t = np.arange(hit_n) / sr
    tone = 0.5 * np.sin(2.0 * np.pi * 190.0 * t) * np.exp(-t / 0.05)
    bp = _sos_bandpass(sr, 1000.0, 8000.0, 2)
    env = _env(hit_n, sr, 0.25, 0.001, 0.05, decay_tau_s=0.09)
    for t0, _ in _cycle_times(seconds, beats):
        noise = _filt(bp, rng.standard_normal(hit_n)) * env
        _add_at(out, frames_for(sr, t0), tone + 0.6 * noise)
    return out[:, None]


def hihat(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    beats: Sequence[float] = tuple(b / 2.0 for b in range(2 * _CYCLE_BEATS)),
) -> FloatArray:
    """Closed hi-hat: high-passed (> 7 kHz) noise bursts on eighth notes."""
    rng = np.random.default_rng([seed, 103])
    n = frames_for(sr, seconds)
    out = np.zeros(n)
    hit_n = frames_for(sr, 0.08)
    hp = _sos_highpass(sr, 7000.0, 4)
    env = _env(hit_n, sr, 0.07, 0.0005, 0.01, decay_tau_s=0.018)
    for t0, i in _cycle_times(seconds, beats):
        accent = 1.0 if i % 2 == 0 else 0.6
        _add_at(out, frames_for(sr, t0), accent * _filt(hp, rng.standard_normal(hit_n)) * env)
    return out[:, None]


def bass_line(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    cutoff_hz: float = 200.0,
) -> FloatArray:
    """Filtered band-limited sawtooth on eighth notes following the chord roots.

    Roots are A1 / F2 / C2 / G2 (55-98 Hz). The low-pass at ``cutoff_hz``
    keeps the energy below 250 Hz.
    """
    del seed  # deterministic without randomness; kept for a uniform signature
    n = frames_for(sr, seconds)
    out = np.zeros(n)
    note_s = _BEAT_S / 2.0
    for t0, _ in _cycle_times(seconds, [b / 2.0 for b in range(2 * _CYCLE_BEATS)]):
        f = midi_to_hz(_chord_at(t0)[1])
        seg_n = frames_for(sr, note_s + 0.03)
        cyc = f * np.arange(seg_n) / sr
        # The polyBLEP saw is -sum(sin(k w t) / k); subtracting a sine reinforces
        # its fundamental.
        tone = _saw(cyc, f / sr) - 0.6 * np.sin(2.0 * np.pi * cyc)
        tone *= _env(seg_n, sr, note_s * 0.9, 0.004, 0.03, decay_tau_s=0.6)
        _add_at(out, frames_for(sr, t0), tone)
    out = _filt(_sos_lowpass(sr, cutoff_hz, 4), out)
    return out[:, None]


def vocal_line(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    transpose: int = 0,
    sibilance: bool = True,
    vowel: str = "a",
    fmax: float = 5000.0,
) -> FloatArray:
    """Vocal-like line: harmonic tone with vibrato, formant filtering, sibilants.

    The melody sits on A3-G4 (220-392 Hz) in A minor. The harmonic source is
    shaped by a high-pass at 150 Hz, formant peaks between 300 Hz and 3 kHz and
    a low-pass at 4.5 kHz; harmonics above ``fmax`` are not generated. With
    ``sibilance`` short noise bursts band-limited to 5-8 kHz are placed at the
    start of every other note (P-17 material). ``vowel`` is ``"a"`` or ``"u"``.
    """
    rng = np.random.default_rng([seed, 104])
    n = frames_for(sr, seconds)
    voiced = np.zeros(n)
    sib = np.zeros(n)
    vib_rate = 5.0 + rng.uniform(0.0, 1.0)
    bp_sib = _sos_bandpass(sr, 5000.0, 8000.0, 4)
    sib_n = frames_for(sr, 0.07)
    sib_env = np.hanning(sib_n)
    melody = _MELODY
    for t0, i in _cycle_times(seconds, [m[0] for m in melody]):
        _, dur_beats, note = melody[i]
        f = midi_to_hz(note + transpose)
        hold = dur_beats * _BEAT_S * 0.92
        seg_n = frames_for(sr, hold + 0.08)
        t = np.arange(seg_n) / sr
        depth_cents = 30.0 * np.minimum(1.0, t / 0.3)
        vib_phase = rng.uniform(0.0, 2.0 * np.pi)
        f_inst = f * 2.0 ** (depth_cents * np.sin(2.0 * np.pi * vib_rate * t + vib_phase) / 1200.0)
        cyc = np.cumsum(f_inst) / sr
        # Harmonics 1/k via complex rotation (cheaper than one sin() per harmonic).
        base = np.exp(2j * np.pi * cyc)
        z = base.copy()
        tone = np.zeros(seg_n)
        k = 1
        while k * f * 1.03 < fmax:
            tone += z.imag / k
            z *= base
            k += 1
        tone *= _env(seg_n, sr, hold, 0.04, 0.08)
        start = frames_for(sr, t0)
        _add_at(voiced, start, tone)
        if sibilance and i % 2 == 0:
            _add_at(sib, start, _filt(bp_sib, rng.standard_normal(sib_n)) * sib_env)
    formants = {"a": ((730.0, 9.0, 4.0), (1090.0, 8.0, 5.0), (2440.0, 6.0, 6.0)),
                "u": ((300.0, 9.0, 3.0), (870.0, 7.0, 4.0), (2240.0, 3.0, 6.0))}[vowel]
    voiced = _filt(_sos_highpass(sr, 150.0, 2), voiced)
    for f0, g, q in formants:
        voiced = _filt(_peaking_sos(sr, f0, g, q), voiced)
    voiced = _filt(_sos_lowpass(sr, 4500.0, 6), voiced)
    voiced = voiced / max(float(np.max(np.abs(voiced))), 1e-12)
    out = voiced + 0.3 * sib / max(float(np.max(np.abs(sib))), 1e-12) if sibilance else voiced
    return out[:, None]


def pad_chords(
    *,
    sr: int = DEFAULT_SR,
    seconds: float = SONG_SECONDS,
    seed: int = 0,
    octave: int = 0,
    detune_cents: float = 8.0,
    cutoff_hz: float = 2500.0,
    attack_s: float = 0.3,
) -> FloatArray:
    """Detuned-saw chord pad, wide stereo (each side has its own detune set).

    Returns a stereo ``(frames, 2)`` array: left and right use different
    detunings and start phases, so they are only partially correlated.
    """
    rng = np.random.default_rng([seed, 105])
    n = frames_for(sr, seconds)
    out = np.zeros((n, 2))
    bar_s = 4 * _BEAT_S
    detunes = ((-detune_cents, detune_cents * 0.4), (-detune_cents * 0.4, detune_cents))
    for t0, _ in _cycle_times(seconds, [0.0, 4.0, 8.0, 12.0]):
        notes = _chord_at(t0)[2]
        seg_n = frames_for(sr, bar_s + 0.3)
        env = _env(seg_n, sr, bar_s, attack_s, 0.3)
        seg = np.zeros((seg_n, 2))
        for ch in range(2):
            for note in notes:
                for d in detunes[ch]:
                    f = midi_to_hz(note + 12 * octave) * 2.0 ** (d / 1200.0)
                    cyc = rng.uniform(0.0, 1.0) + f * np.arange(seg_n) / sr
                    seg[:, ch] += _saw(cyc, f / sr)
        _add_at(out, frames_for(sr, t0), seg * env[:, None])
    out = _filt(_sos_lowpass(sr, cutoff_hz, 2), out)
    return out


def _plucks(sr: int, seconds: float, beats: Sequence[float], note_of, decay_s: float,
            cutoff_hz: float, length_s: float) -> FloatArray:
    """Decaying saw notes at cycle beats; ``note_of(t, i)`` gives MIDI notes."""
    n = frames_for(sr, seconds)
    out = np.zeros(n)
    for t0, i in _cycle_times(seconds, beats):
        for note in note_of(t0, i):
            f = midi_to_hz(note)
            seg_n = frames_for(sr, length_s)
            cyc = f * np.arange(seg_n) / sr
            tone = _saw(cyc, f / sr) * _env(seg_n, sr, length_s - 0.03, 0.003, 0.03, decay_tau_s=decay_s)
            _add_at(out, frames_for(sr, t0), tone)
    return _filt(_sos_lowpass(sr, cutoff_hz, 2), out)


# ---------------------------------------------------------------------------
# The song
# ---------------------------------------------------------------------------


def _norm(x: FloatArray) -> FloatArray:
    peak = float(np.max(np.abs(x))) if x.size else 0.0
    return x / peak if peak > 0 else x


def song_stems(sr: int = DEFAULT_SR, seconds: float = SONG_SECONDS, seed: int = 0,
               mix_peak_dbfs: float = -6.0) -> dict[str, FloatArray]:
    """A short deterministic stereo "song" as twelve stems (SPEC section 6.1.3 roles).

    120 BPM, A minor, progression Am-F-C-G (one chord per 2 s bar). The first
    half is a quiet section (pad, soft vocal, soft bass, keyboard, hats,
    woodwinds); the second half is a loud section (full drums, strings,
    brass, backing vocals, percussion, guitar; see :func:`song_sections`). An
    fx riser leads into the loud section.

    All stems are stereo ``(frames, 2)`` and head aligned, and all are scaled
    by one common factor so that the gain-0 stem sum peaks at
    ``mix_peak_dbfs``. Keys follow :data:`SONG_ROLES`.
    """
    n = frames_for(sr, seconds)

    weight = _section_weight(n, sr, seconds)

    def sect(quiet_db, loud_db):
        return _section_curve(weight, quiet_db, loud_db)

    def sub(k: int) -> int:
        # Independent, deterministic sub-seed per part.
        return int(np.random.default_rng([seed, k]).integers(0, 2**31 - 1))

    stems: dict[str, FloatArray] = {}

    # Drums: kick + snare centre, hats slightly right.
    k = _norm(kick(sr=sr, seconds=seconds, seed=sub(1)))[:, 0]
    s = _norm(snare(sr=sr, seconds=seconds, seed=sub(2)))[:, 0]
    h = _norm(hihat(sr=sr, seconds=seconds, seed=sub(3)))[:, 0]
    stems["drums"] = (
        _pan(k, 0.0) * sect(None, 0.0)
        + _pan(s, 0.05) * sect(None, -4.0)
        + _pan(h, 0.3) * sect(-14.0, -10.0)
    )

    stems["bass"] = _pan(_norm(bass_line(sr=sr, seconds=seconds, seed=sub(4)))[:, 0], 0.0) * sect(-9.0, -1.0)

    v = _norm(vocal_line(sr=sr, seconds=seconds, seed=sub(5)))[:, 0]
    stems["vocals"] = _pan(v, 0.0) * sect(-8.0, -2.0)

    # Backing vocals: a fourth below the lead, "oo" vowel, double-tracked by a
    # 17 ms copy on the other side (wide but correlated).
    bv = _norm(vocal_line(sr=sr, seconds=seconds, seed=sub(6), transpose=-5, sibilance=False,
                          vowel="u", fmax=3500.0))[:, 0]
    lag = min(frames_for(sr, 0.017), n)
    bv_late = np.concatenate([np.zeros(lag), bv[: n - lag]])
    stems["backing_vocals"] = (_pan(bv, -0.7) + _pan(bv_late, 0.7)) * sect(None, -10.0)

    stems["synth"] = _norm(pad_chords(sr=sr, seconds=seconds, seed=sub(8))) * sect(-8.0, -7.0)

    def keys_notes(t, i):
        return _chord_at(t)[2]
    kb = _plucks(sr, seconds, [0.0, 1.5, 4.0, 5.5, 8.0, 9.5, 12.0, 13.5], keys_notes, 0.5, 3500.0, 1.2)
    stems["keyboard"] = _pan(_norm(kb), -0.25) * sect(-12.0, -14.0)

    def guitar_notes(t, i):
        chord = _chord_at(t)[2]
        return (chord[i % 3] + 12,)
    gt = _plucks(sr, seconds, [b / 2.0 for b in range(2 * _CYCLE_BEATS)], guitar_notes, 0.18, 4000.0, 0.4)
    gt = _filt(_sos_highpass(sr, 150.0, 2), gt)
    stems["guitar"] = _pan(_norm(gt), -0.55) * sect(None, -13.0)

    st = pad_chords(sr=sr, seconds=seconds, seed=sub(9), octave=1, detune_cents=12.0,
                    cutoff_hz=5000.0, attack_s=0.5)
    stems["strings"] = _norm(st) * sect(None, -12.0)

    def brass_notes(t, i):
        return tuple(m + 12 for m in _chord_at(t)[2][:2])
    bs = _plucks(sr, seconds, [1.0, 3.0, 5.0, 7.0, 9.0, 11.0, 13.0, 15.0], brass_notes, 0.25, 3500.0, 0.35)
    stems["brass"] = _pan(_norm(bs), 0.35) * sect(None, -14.0)

    # Woodwinds: flute-ish long tones an octave above the melody, breathy.
    rng_w = np.random.default_rng([seed, 10])
    ww = np.zeros(n)
    for t0, i in _cycle_times(seconds, [0.0, 4.0, 8.0, 12.0]):
        f = midi_to_hz(_chord_at(t0)[2][2] + 12)
        seg_n = frames_for(sr, 4 * _BEAT_S)
        t = np.arange(seg_n) / sr
        cyc = np.cumsum(f * 2.0 ** (15.0 * np.sin(2.0 * np.pi * 5.2 * t) / 1200.0)) / sr
        tone = np.sin(2.0 * np.pi * cyc) + 0.25 * np.sin(4.0 * np.pi * cyc)
        breath = _filt(_sos_bandpass(sr, 2000.0, 6000.0, 2), rng_w.standard_normal(seg_n)) * 0.08
        _add_at(ww, frames_for(sr, t0), (tone + breath) * _env(seg_n, sr, 4 * _BEAT_S - 0.2, 0.12, 0.15))
    stems["woodwinds"] = _pan(_norm(ww), 0.45) * sect(-14.0, -18.0)

    # Percussion: shaker on sixteenths alternating sides.
    rng_p = np.random.default_rng([seed, 11])
    pl = np.zeros(n)
    pr = np.zeros(n)
    hit_n = frames_for(sr, 0.06)
    bp = _sos_bandpass(sr, 4000.0, 10000.0, 2)
    env = _env(hit_n, sr, 0.05, 0.004, 0.01, decay_tau_s=0.02)
    for t0, i in _cycle_times(seconds, [b / 4.0 for b in range(4 * _CYCLE_BEATS)]):
        hit = _filt(bp, rng_p.standard_normal(hit_n)) * env * (1.0 if i % 4 == 2 else 0.5)
        _add_at(pl if i % 2 == 0 else pr, frames_for(sr, t0), hit)
    perc = _norm(np.stack([pl + 0.3 * pr, pr + 0.3 * pl], axis=1))
    stems["percussion"] = perc * sect(None, -16.0)

    # FX: riser (log sweep + noise swell) into the loud section, then a downlifter.
    b = song_sections(seconds)["loud"][0]
    fx = np.zeros((n, 2))
    riser_s = min(2.0, b)
    rs_n = frames_for(sr, riser_s)
    if rs_n > 0:
        ramp = np.linspace(0.0, 1.0, rs_n) ** 2
        sw = sweep(300.0, 6000.0, 0.0, sr=sr, seconds=riser_s)[:, 0] * ramp
        rng_f = np.random.default_rng([seed, 12])
        swell = _filt(_sos_highpass(sr, 3000.0, 2), rng_f.standard_normal((rs_n, 2))) * ramp[:, None] * 0.3
        lfo = 0.5 * np.sin(2.0 * np.pi * 1.5 * np.arange(rs_n) / sr)
        seg = _pan(sw, 0.0) * np.stack([1.0 - lfo, 1.0 + lfo], axis=1) + swell
        _add_at(fx, frames_for(sr, b - riser_s), seg)
    dn_s = min(1.0, max(seconds - b, 0.0))
    dn_n = frames_for(sr, dn_s)
    if dn_n > 0:
        dn = sweep(2000.0, 100.0, 0.0, sr=sr, seconds=dn_s)[:, 0] * np.linspace(1.0, 0.0, dn_n)
        _add_at(fx, frames_for(sr, b), _pan(dn, -0.2))
    stems["fx"] = _norm(fx) * db_to_amp(-16.0)

    stems = {role: stems[role] for role in SONG_ROLES}
    total_peak = float(np.max(np.abs(stem_sum(stems))))
    scale = db_to_amp(mix_peak_dbfs) / total_peak if total_peak > 0 else 1.0
    return {role: np.ascontiguousarray(x * scale) for role, x in stems.items()}


# ---------------------------------------------------------------------------
# AI-generated-audio defect injectors (SPEC section 6.4, P-16)
# ---------------------------------------------------------------------------


def add_hf_ceiling(x: FloatArray, sr: int, cutoff_hz: float = 16000.0) -> FloatArray:
    """Steep zero-phase elliptic low-pass: the "high-frequency ceiling" defect.

    The passband ends at 0.95 * ``cutoff_hz`` and everything at and above
    ``cutoff_hz`` is attenuated by well over 100 dB (filtered forward and
    backward, so there is no delay).
    """
    x2 = _as_2d(x)
    nyq = sr / 2.0
    if not 0 < cutoff_hz < nyq:
        raise ValueError("cutoff_hz must be between 0 and Nyquist")
    order, wn = signal.ellipord(0.95 * cutoff_hz, cutoff_hz, 0.1, 80.0, fs=sr)
    sos = signal.ellip(order, 0.1, 80.0, wn, btype="lowpass", fs=sr, output="sos")
    return signal.sosfiltfilt(sos, x2, axis=0)


def _band_noise(n: int, channels: int, sr: int, band: tuple[float, float], rng) -> FloatArray:
    """White noise brick-wall limited to ``band`` in the frequency domain."""
    spec = np.fft.rfft(rng.standard_normal((n, channels)), axis=0)
    f = np.fft.rfftfreq(n, d=1.0 / sr)
    spec[(f < band[0]) | (f > band[1])] = 0.0
    return np.fft.irfft(spec, n=n, axis=0)


def _smooth_env(x2: FloatArray, sr: int, window_s: float = 0.02) -> FloatArray:
    """RMS envelope per channel with a Hann smoothing window."""
    w = np.hanning(max(3, frames_for(sr, window_s)))
    w /= w.sum()
    p = np.stack([np.convolve(np.square(x2[:, c]), w, mode="same") for c in range(x2.shape[1])], axis=1)
    return np.sqrt(np.maximum(p, 0.0))


def add_shimmer(
    x: FloatArray,
    sr: int,
    band: tuple[float, float] = (10000.0, 14000.0),
    depth_db: float = -24.0,
    seed: int = 0,
    mod_hz: tuple[float, float] = (3.0, 11.0),
) -> FloatArray:
    """Add signal-correlated, amplitude-modulated noise confined to ``band``.

    The shimmer is band-limited noise (independent per channel) multiplied by
    the input's smoothed envelope (so it follows the music: signal correlated)
    and by a random multi-LFO tremolo in the ``mod_hz`` range (so it warbles).
    ``depth_db`` is the RMS of the added component relative to the RMS of the
    input. The added component (``y - x``) has essentially no energy outside
    ``band``.
    """
    x2 = _as_2d(x)
    n, ch = x2.shape
    rng = np.random.default_rng([seed, 201])
    noise = _band_noise(n, ch, sr, band, rng)
    env = _smooth_env(x2.mean(axis=1, keepdims=True), sr)  # common envelope
    t = np.arange(n) / sr
    lfo = np.zeros(n)
    for _ in range(3):
        lfo += np.sin(2.0 * np.pi * rng.uniform(*mod_hz) * t + rng.uniform(0.0, 2.0 * np.pi))
    trem = 0.5 + 0.5 * np.tanh(1.5 * lfo)  # 0..1, strongly modulated
    shimmer = noise * env * trem[:, None]
    rms_s = math.sqrt(float(np.mean(np.square(shimmer))))
    rms_x = math.sqrt(float(np.mean(np.square(x2))))
    if rms_s == 0.0 or rms_x == 0.0:
        return x2.copy()
    return x2 + shimmer * (rms_x * db_to_amp(depth_db) / rms_s)


def add_head_click(x: FloatArray, sr: int, at_s: float = 0.0, dbfs: float = -6.0,
                   freq: float = 3000.0, length_ms: float = 2.0) -> FloatArray:
    """Add a short click (sharp decaying 3 kHz transient, peak ``dbfs``) at ``at_s``.

    Default position is the very first sample, like the head click of many
    AI-generated renders (SPEC section 6.4.2 step 2).
    """
    x2 = _as_2d(x).copy()
    m = max(2, frames_for(sr, length_ms / 1000.0))
    t = np.arange(m) / sr
    click = np.cos(2.0 * np.pi * freq * t) * np.exp(-t / (length_ms / 1000.0 / 5.0))
    click *= db_to_amp(dbfs) / float(np.max(np.abs(click)))
    start = frames_for(sr, at_s)
    for c in range(x2.shape[1]):
        _add_at(x2[:, c], start, click)
    return x2


def add_noise_floor(x: FloatArray, sr: int, dbfs: float = -60.0, seed: int = 0,
                    color: str = "white") -> FloatArray:
    """Add stationary noise (``white`` or ``pink``) with RMS ``dbfs`` per channel."""
    x2 = _as_2d(x)
    n, ch = x2.shape
    seconds = n / sr
    gen = {"white": white_noise, "pink": pink_noise}[color]
    noise = gen(dbfs, sr=sr, seconds=seconds, seed=seed, channels=ch)[:n]
    return x2 + noise


def add_lowmid_buildup(x: FloatArray, sr: int, gain_db: float = 6.0,
                       center_hz: float = 350.0, q: float = 0.9) -> FloatArray:
    """Boost the 250-500 Hz low-mid region with a peaking EQ (muddy density)."""
    return _filt(_peaking_sos(sr, center_hz, gain_db, q), _as_2d(x))


def make_overlimited(x: FloatArray, sr: int, drive_db: float = 18.0,
                     ceiling_dbfs: float = -0.1) -> FloatArray:
    """Crush a mix: drive by ``drive_db`` above full peak, then clip at the ceiling.

    Models an over-limited, already-mastered 2mix (low PLR / crest factor,
    flat-topped waveform; SPEC 6.1.4 headroom check, P-03, P-18).
    """
    del sr  # signature kept uniform with the other injectors
    x2 = normalize_peak(_as_2d(x), 0.0) * db_to_amp(drive_db)
    ceiling = db_to_amp(ceiling_dbfs)
    soft = np.tanh(x2 / ceiling) * ceiling
    return np.clip(soft * 1.05, -ceiling, ceiling)


def add_dc(x: FloatArray, offset: float = 0.01) -> FloatArray:
    """Add a constant DC ``offset`` (linear, e.g. 0.01 = -40 dBFS) to all channels."""
    return _as_2d(x) + float(offset)


def inject_nan(x: FloatArray, positions: Sequence[int] = (0,), channel: int = 0,
               value: float = float("nan")) -> FloatArray:
    """Return a copy with ``value`` (NaN by default; pass ``inf`` too) at frames ``positions``."""
    x2 = _as_2d(x).copy()
    for p in positions:
        x2[int(p), channel] = value
    return x2


def antiphase_low(x: FloatArray, sr: int, below_hz: float = 120.0) -> FloatArray:
    """Invert the band below ``below_hz`` on the right channel (S-03 violation).

    The split is a zero-phase complementary crossover (low + high == input),
    so the band above ``below_hz`` is untouched. Mono input becomes stereo.
    """
    x2 = _as_2d(x)
    if x2.shape[1] == 1:
        x2 = np.repeat(x2, 2, axis=1)
    sos = _sos_lowpass(sr, below_hz, 4)
    right = x2[:, 1]
    low = signal.sosfiltfilt(sos, right)
    out = x2.copy()
    out[:, 1] = (right - low) - low
    return out


# ---------------------------------------------------------------------------
# Reference master with known processing (raw-reference path, route 2 material A)
# ---------------------------------------------------------------------------


def tilt_eq(x: FloatArray, sr: int, db_per_oct: float, pivot_hz: float = 1000.0) -> FloatArray:
    """Zero-phase spectral tilt: gain ``db_per_oct * log2(f / pivot_hz)`` dB (f clamped to 20 Hz..Nyquist)."""
    x2 = _as_2d(x)
    n = x2.shape[0]
    f = np.fft.rfftfreq(n, 1.0 / sr)
    fc = np.clip(f, 20.0, sr / 2.0)
    g = 10.0 ** (float(db_per_oct) * np.log2(fc / float(pivot_hz)) / 20.0)
    return np.fft.irfft(np.fft.rfft(x2, axis=0) * g[:, None], n=n, axis=0)


def peak_limit(x: FloatArray, sr: int, ceiling_dbfs: float = -1.0, lookahead_s: float = 0.005) -> FloatArray:
    """Look-ahead peak limiter (linked stereo): the sample peak never exceeds ``ceiling_dbfs``.

    The needed gain is min-filtered over +-lookahead and then averaged over a
    window no wider than that, so every smoothed gain stays at or below the
    gain needed at each sample (deterministic, no state)."""
    from scipy import ndimage
    x2 = _as_2d(x)
    ceil = db_to_amp(ceiling_dbfs)
    peak = np.max(np.abs(x2), axis=1)
    need = np.minimum(1.0, ceil / np.maximum(peak, 1e-12))
    la = max(1, int(round(lookahead_s * sr)))
    g = ndimage.minimum_filter1d(need, size=2 * la + 1, mode="nearest")
    g = ndimage.uniform_filter1d(g, size=la + 1, mode="nearest")
    g = np.minimum(g, ndimage.minimum_filter1d(need, size=la + 1, mode="nearest"))
    return x2 * g[:, None]


def reference_master_set(sr: int = DEFAULT_SR, seconds: float = SONG_SECONDS, seed: int = 0,
                         tilt_db_per_oct: float = 1.5, drive_db: float = 10.0,
                         ceiling_dbfs: float = -1.0) -> dict:
    """A "master" with known processing and the stems it was made from (arrays, nothing written).

    master = peak_limit(tilt_eq(stem_sum(song_stems)) normalised to 0 dBFS peak + drive_db).
    Returns {"master", "stems", "sr", "tilt_db_per_oct", "drive_db", "ceiling_dbfs"}."""
    stems = song_stems(sr=sr, seconds=seconds, seed=seed)
    eq = tilt_eq(stem_sum(stems), sr, tilt_db_per_oct)
    master = peak_limit(normalize_peak(eq, 0.0) * db_to_amp(drive_db), sr, ceiling_dbfs)
    return {"master": master, "stems": stems, "sr": sr, "tilt_db_per_oct": float(tilt_db_per_oct),
            "drive_db": float(drive_db), "ceiling_dbfs": float(ceiling_dbfs)}


# ---------------------------------------------------------------------------
# Stem summing and file helpers
# ---------------------------------------------------------------------------


def stem_sum(stems: Mapping[str, FloatArray] | Iterable[FloatArray]) -> FloatArray:
    """Gain-0, head-aligned sum of stems (SPEC section 15.2 "Before").

    Shorter stems are zero padded at the end; mono stems are broadcast to the
    widest channel count. Other channel-count mismatches raise ``ValueError``.
    """
    arrays = [_as_2d(a) for a in (stems.values() if isinstance(stems, Mapping) else stems)]
    if not arrays:
        raise ValueError("stem_sum needs at least one stem")
    n = max(a.shape[0] for a in arrays)
    ch = max(a.shape[1] for a in arrays)
    out = np.zeros((n, ch))
    for a in arrays:
        if a.shape[1] not in (1, ch):
            raise ValueError(f"cannot sum a {a.shape[1]}-channel stem into {ch} channels")
        out[: a.shape[0]] += a
    return out


def write_wav(path: str | Path, x: FloatArray, sr: int, subtype: str = "FLOAT") -> Path:
    """Write ``x`` to a WAV file (parent folders are created).

    For integer PCM subtypes the signal is clipped to [-1, 1] first, which is
    what a real PCM export would contain.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    data = _as_2d(x)
    if not subtype.upper().startswith(("FLOAT", "DOUBLE")):
        data = np.clip(data, -1.0, 1.0)
    sf.write(str(path), data, int(sr), subtype=subtype, format="WAV")
    return path


def read_wav(path: str | Path) -> tuple[FloatArray, int]:
    """Read an audio file as float64 ``(frames, channels)`` plus its sample rate."""
    data, sr = sf.read(str(path), dtype="float64", always_2d=True)
    return data, int(sr)
